# 466 — Participle clauses
# ---------------------------------------------------------------------------
data["466"] = [
 {"title":"Open cloze (avançado) — Orações reduzidas com particípio (fiscal-taxes)","note":"Sem opções. O aluno produz o elemento que falta.","items":[
   {"q":"___ on that confidence, every strategic conversation becomes easier.","a":"Built"},
   {"q":"___ quietly for years, the discipline of clean calculation becomes credibility.","a":"Done / Practised"},
   {"q":"___ the effective rate against the statutory rate, we identified a significant variance.","a":"Comparing / Reconciling"},
   {"q":"___ traced to source, every figure in the return can withstand scrutiny.","a":"Once"},
   {"q":"The calculation, ___ reconstructed from primary records, held up under audit.","a":"having been"},
   {"q":"___ confronted with the discrepancy, the desk produced its working papers immediately.","a":"When"},
   {"q":"___ each adjustment in a single workbook, the team made the rate fully auditable.","a":"Documenting / Recording"},
   {"q":"The reconstruction, ___ painstaking, ultimately restored the auditor's confidence.","a":"though / however"},
   {"q":"___ left unchecked, small variances accumulate into material problems.","a":"If / When"},
   {"q":"___ by years of consistency, the figures rarely wobble under questioning.","a":"Supported / Underpinned"}]},
 {"title":"Key word transformation — reduza a oração com particípio (orações participiais)","note":"Reescreva usando a palavra-chave (3–6 palavras).","items":[
   {"q":"Because it was built on confidence, the conversation was easier.  ·  (BUILT)  ·  ___ on confidence, the conversation was easier.","a":"Built"},
   {"q":"After it had been reconstructed, the calculation held up.  ·  (HAVING)  ·  ___ reconstructed, the calculation held up.","a":"Having been"},
   {"q":"When you trace every figure to source, the return is defensible.  ·  (TRACED)  ·  ___ to source, the return is defensible.","a":"Traced to source"},
   {"q":"As we compared the rates, we found a variance.  ·  (COMPARING)  ·  ___ the rates, we found a variance.","a":"Comparing the rates"},
   {"q":"Although it was painstaking, the work restored confidence.  ·  (THOUGH)  ·  Painstaking ___ , the work restored confidence.","a":"though it was"},
   {"q":"Since they are supported by consistency, the figures hold.  ·  (SUPPORTED)  ·  ___ by consistency, the figures hold.","a":"Supported"}]},
 {"title":"Register / paraphrase — eleve ao registro executivo (orações participiais)","note":"Reescreva em registro formal usando oração reduzida com particípio.","items":[
   {"q":"Because we'd done it quietly for years, it had become credibility.","a":"Done quietly for years, the discipline had quietly become credibility."},
   {"q":"When we compared the two rates, we spotted a big gap.","a":"Comparing the effective rate with the statutory rate, we identified a significant variance."},
   {"q":"After the calculation had been rebuilt, it survived the audit.","a":"Having been reconstructed from source, the calculation withstood the audit."},
   {"q":"If you leave small variances alone, they pile up.","a":"Left unchecked, small variances accumulate into material problems."},
   {"q":"Since every figure could be traced, the return was defensible.","a":"Every figure traced to source, the return proved entirely defensible."},
   {"q":"Although the work was painstaking, it restored their confidence.","a":"Painstaking though it was, the reconstruction restored the auditor's confidence."}]},
 {"title":"Error correction (editing) — ache e corrija o erro sutil (orações participiais)","note":"Um erro de C1/C2 por frase. Corrija e diga por quê.","items":[
   {"q":"Build on that confidence, every conversation becomes easier.","a":"Built on that confidence, every conversation becomes easier. (oração reduzida passiva usa particípio 'Built')"},
   {"q":"Having reconstructed from source, the calculation held up.","a":"Having been reconstructed from source, the calculation held up. (a calculação sofre a ação: passiva 'having been reconstructed')"},
   {"q":"Comparing the rates, a variance was found by us.","a":"Comparing the rates, we found a variance. (o sujeito do particípio deve ser 'we', evitando particípio pendente)"},
   {"q":"Traced to source, we could defend every figure with the return.","a":"Traced to source, every figure could be defended. (o particípio refere-se às 'figures', não a 'we')"},
   {"q":"Leaving unchecked, small variances accumulate.","a":"Left unchecked, small variances accumulate. (sentido passivo exige particípio passado 'Left')"},
   {"q":"Painstaking though was, the work restored confidence.","a":"Painstaking though it was, the work restored confidence. (a concessiva exige o sujeito 'it')"}]},
 {"title":"Advanced collocations & lexis — disciplina de cálculo fiscal (além da aula)","note":"Peça uma frase de registro formal com cada item.","items":[
   {"q":"to withstand scrutiny","a":"resistir ao escrutínio"},{"q":"to trace a figure to source","a":"rastrear um número até a origem"},
   {"q":"an audit trail","a":"uma trilha de auditoria"},{"q":"to hold up under questioning","a":"sustentar-se sob questionamento"},
   {"q":"working papers","a":"papéis de trabalho"},{"q":"to reconcile a variance","a":"conciliar uma divergência"},
   {"q":"to underpin a number","a":"dar lastro a um número"},{"q":"a material variance","a":"uma divergência relevante"},
   {"q":"primary records","a":"registros primários"},{"q":"to stand up to challenge","a":"resistir a uma contestação"}]},
 {"title":"Discuss / Argue — orações participiais no seu trabalho","note":"Respostas-modelo C1–C2 que o aluno adapta.","items":[
   {"q":"Why do you treat tax calculation as a discipline rather than a task?","a":"Done quietly and consistently for years, clean calculation ceases to be a chore and becomes the very foundation of executive trust."},
   {"q":"How do you ensure a figure can survive an audit?","a":"Traced to source and reconciled to primary records, every figure in our returns is built to withstand scrutiny long before any auditor arrives."},
   {"q":"Describe how you handled a variance between statutory and effective rates.","a":"Comparing the two rates closely, we isolated the variance, and, having reconstructed each adjustment from source, we could explain it without hesitation."},
   {"q":"What is the danger of ignoring small discrepancies?","a":"Left unchecked, minor variances accumulate into material problems, which is why we resolve them while they are still trivial."},
   {"q":"How does consistency in calculation build credibility?","a":"Underpinned by years of consistency, our figures rarely wobble under questioning, and that steadiness is, in itself, a form of credibility."},
   {"q":"Why invest effort in a painstaking reconstruction?","a":"Painstaking though it is, a full reconstruction from source restores the auditor's confidence in a way no summary ever could."}]}
]

