data["467"] = [
 {"title":"Open cloze (avançado) — Sintagmas nominais abstratos (fiscal-taxes)","note":"Sem opções. O aluno produz o elemento que falta.","items":[
   {"q":"The distinction ___ the marginal and the effective rate is the heart of rate design.","a":"between"},
   {"q":"The quality ___ every investment decision turns on understanding the rate on the next pound.","a":"of"},
   {"q":"The simplicity ___ the discipline belies its strategic importance.","a":"of"},
   {"q":"The progression ___ rates across brackets reflects deliberate policy choices.","a":"of"},
   {"q":"The application ___ the marginal rate to the next hire shapes our recruitment calculus.","a":"of"},
   {"q":"The reduction ___ the effective rate, achieved through deductions, is closely watched by investors.","a":"of / in"},
   {"q":"It is the persistence ___ the misunderstanding that frustrates the finance team.","a":"of"},
   {"q":"The confusion ___ marginal and average rates leads to poor investor communication.","a":"of / between"},
   {"q":"The relevance ___ marginal thinking to a price increase is often overlooked.","a":"of"},
   {"q":"The clarity ___ the distinction matters more than the sophistication of the model.","a":"of"}]},
 {"title":"Key word transformation — abstraia em sintagma nominal (sintagmas abstratos)","note":"Reescreva usando a palavra-chave (3–6 palavras).","items":[
   {"q":"Marginal and effective rates are distinct, and that distinction is central.  ·  (DISTINCTION)  ·  The ___ is central.","a":"distinction between the two rates"},
   {"q":"Rates progress across the brackets in a deliberate way.  ·  (PROGRESSION)  ·  The ___ is deliberate.","a":"progression of rates"},
   {"q":"We apply the marginal rate to the next hire, which shapes decisions.  ·  (APPLICATION)  ·  The ___ shapes decisions.","a":"application of the marginal rate"},
   {"q":"People keep confusing the two rates, which frustrates the team.  ·  (CONFUSION)  ·  The ___ frustrates the team.","a":"confusion of the two rates"},
   {"q":"We reduced the effective rate, and investors noticed.  ·  (REDUCTION)  ·  The ___ was noticed by investors.","a":"reduction of the effective rate"},
   {"q":"The discipline is simple, and that's the point.  ·  (SIMPLICITY)  ·  The ___ is precisely the point.","a":"simplicity of the discipline"}]},
 {"title":"Register / paraphrase — eleve ao registro executivo (sintagmas abstratos)","note":"Reescreva em registro formal usando sintagma nominal abstrato.","items":[
   {"q":"It really matters that you can tell the two rates apart.","a":"The distinction between the marginal and the effective rate is of decisive importance."},
   {"q":"People keep getting marginal and average rates mixed up.","a":"The persistent confusion of marginal and average rates undermines clear communication."},
   {"q":"When you apply the marginal rate to the next hire, it changes how you decide.","a":"The application of the marginal rate to each incremental hire reshapes the recruitment calculus."},
   {"q":"We cut the effective rate, and investors paid attention.","a":"The reduction of the effective rate did not escape investor attention."},
   {"q":"The discipline is simple, but that's exactly why it's powerful.","a":"It is the very simplicity of the discipline that accounts for its strategic power."},
   {"q":"Rates go up step by step, and that's a policy choice.","a":"The progression of rates across the brackets reflects a deliberate choice of policy."}]},
 {"title":"Error correction (editing) — ache e corrija o erro sutil (sintagmas abstratos)","note":"Um erro de C1/C2 por frase. Corrija e diga por quê.","items":[
   {"q":"The distinction of the marginal and effective rate is central.","a":"The distinction between the marginal and effective rate is central. (colocação: 'distinction between')"},
   {"q":"The progression of rates reflect deliberate policy.","a":"The progression of rates reflects deliberate policy. (núcleo singular 'progression' exige 'reflects')"},
   {"q":"The confusion between the two rates lead to poor communication.","a":"The confusion of the two rates leads to poor communication. (núcleo singular exige 'leads')"},
   {"q":"It is the simplicity of the discipline what makes it powerful.","a":"It is the simplicity of the discipline that makes it powerful. (cleft usa 'that', não 'what')"},
   {"q":"The application the marginal rate shapes our decisions.","a":"The application of the marginal rate shapes our decisions. (nominalização exige 'of')"},
   {"q":"The reduction in the effective rate were noticed by investors.","a":"The reduction in the effective rate was noticed by investors. (sujeito singular exige 'was')"}]},
 {"title":"Advanced collocations & lexis — desenho de alíquotas (além da aula)","note":"Peça uma frase de registro formal com cada item.","items":[
   {"q":"the rate on the next pound","a":"a alíquota sobre a próxima libra"},{"q":"to be persistently misunderstood","a":"ser cronicamente mal compreendido"},
   {"q":"a tax bracket","a":"uma faixa tributária"},{"q":"marginal thinking","a":"raciocínio marginal"},
   {"q":"to bridge the statutory–effective gap","a":"conciliar a alíquota legal e a efetiva"},{"q":"incremental decision-making","a":"tomada de decisão incremental"},
   {"q":"to skew the average","a":"distorcer a média"},{"q":"a deliberate policy choice","a":"uma escolha deliberada de política"},
   {"q":"investor communication","a":"comunicação com investidores"},{"q":"to risk sounding pedantic","a":"correr o risco de soar pedante"}]},
 {"title":"Discuss / Argue — sintagmas abstratos no seu trabalho","note":"Respostas-modelo C1–C2 que o aluno adapta.","items":[
   {"q":"Why does the marginal–effective distinction matter to decision-making?","a":"It is the distinction between the marginal and the effective rate that determines the quality of every incremental decision, from a price increase to an additional hire."},
   {"q":"How do you avoid sounding pedantic when correcting this confusion?","a":"I frame the clarification around the consequence — the application of the wrong rate to the next pound — rather than the terminology, so the persistence of the misunderstanding becomes the team's problem, not mine."},
   {"q":"What do investors actually watch in your rate disclosures?","a":"What investors track is the reduction of the effective rate and its sustainability, not the statutory figure, which is why the bridge between the two demands such care."},
   {"q":"Explain why a simple discipline can be strategically powerful.","a":"It is precisely the simplicity of the discipline — knowing the rate on the next pound — that gives it such reach across pricing, hiring and investment."},
   {"q":"How does marginal thinking shape a recruitment decision?","a":"The application of the marginal rate to each incremental hire reframes the decision from a question of headcount into one of after-tax return."},
   {"q":"Why is the progression of rates a strategic, not merely a technical, matter?","a":"The progression of rates across the brackets is a deliberate policy choice, and reading it correctly is what allows us to anticipate where the next pound of profit will be most heavily taxed."}]}
]

