data["468"] = [
 {"title":"Open cloze (avançado) — Construções passivas formais (fiscal-taxes)","note":"Sem opções. O aluno produz o elemento que falta.","items":[
   {"q":"Costs are ___ where they make genuine economic sense.","a":"booked / allocated"},
   {"q":"Revenue is ___ by the entity that genuinely earns it.","a":"recognised"},
   {"q":"The taxable base is ___ through the application of allowable deductions.","a":"adjusted / reduced"},
   {"q":"Management fees are ___ across entities in line with the value each receives.","a":"allocated / apportioned"},
   {"q":"Timing differences are ___ in the period in which they arise.","a":"recognised / recorded"},
   {"q":"Where revenue ___ recognised correctly, the resulting position is defensible.","a":"is"},
   {"q":"Profit is ___ to the entity that bears the corresponding risk.","a":"attributed / allocated"},
   {"q":"The boundary between sound and aggressive planning is ___ defined in our policy.","a":"clearly / carefully"},
   {"q":"Deductions are ___ only where they are genuinely supported by economic substance.","a":"claimed / taken"},
   {"q":"The reduction of the effective rate is ___ through legitimate structural choices.","a":"achieved"}]},
 {"title":"Key word transformation — para a passiva formal (passiva formal)","note":"Reescreva usando a palavra-chave (3–6 palavras).","items":[
   {"q":"We book costs where they make economic sense.  ·  (BOOKED)  ·  Costs ___ where they make economic sense.","a":"are booked"},
   {"q":"The entity that earns the revenue recognises it.  ·  (RECOGNISED)  ·  Revenue ___ by the entity that earns it.","a":"is recognised"},
   {"q":"We allocate management fees across the entities.  ·  (ALLOCATED)  ·  Management fees ___ across the entities.","a":"are allocated"},
   {"q":"Allowable deductions reduce the taxable base.  ·  (REDUCED)  ·  The taxable base ___ by allowable deductions.","a":"is reduced"},
   {"q":"We attribute profit to whoever bears the risk.  ·  (ATTRIBUTED)  ·  Profit ___ to whoever bears the risk.","a":"is attributed"},
   {"q":"Legitimate choices achieve the rate reduction.  ·  (ACHIEVED)  ·  The rate reduction ___ through legitimate choices.","a":"is achieved"}]},
 {"title":"Register / paraphrase — eleve ao registro executivo (passiva formal)","note":"Reescreva em registro formal usando passiva impessoal.","items":[
   {"q":"We put the costs wherever they make sense for the business.","a":"Costs are booked where they make genuine economic sense."},
   {"q":"The company that actually earns the money recognises the revenue.","a":"Revenue is recognised by the entity that genuinely earns it."},
   {"q":"We adjusted the numbers to get a lower tax bill.","a":"The taxable base was adjusted through the application of allowable deductions, yielding a lower effective rate."},
   {"q":"We split the management fees between the companies fairly.","a":"Management fees are allocated across entities in proportion to the value each receives."},
   {"q":"We only take deductions when there's real substance behind them.","a":"Deductions are claimed only where they are genuinely supported by economic substance."},
   {"q":"We give the profit to whichever entity carries the risk.","a":"Profit is attributed to the entity that bears the corresponding risk."}]},
 {"title":"Error correction (editing) — ache e corrija o erro sutil (passiva formal)","note":"Um erro de C1/C2 por frase. Corrija e diga por quê.","items":[
   {"q":"Costs are book where they make economic sense.","a":"Costs are booked where they make economic sense. (passiva exige particípio 'booked')"},
   {"q":"Revenue is recognised from the entity that earns it.","a":"Revenue is recognised by the entity that earns it. (agente da passiva é introduzido por 'by')"},
   {"q":"The taxable base was adjust through allowable deductions.","a":"The taxable base was adjusted through allowable deductions. (particípio 'adjusted')"},
   {"q":"Management fees is allocated across the entities.","a":"Management fees are allocated across the entities. ('fees' é plural, exige 'are')"},
   {"q":"Profit is attributed at the entity that bears the risk.","a":"Profit is attributed to the entity that bears the risk. (colocação: 'attributed to')"},
   {"q":"Deductions are claimed only where there are genuine substance.","a":"Deductions are claimed only where there is genuine substance. ('substance' é incontável: 'there is')"}]},
 {"title":"Advanced collocations & lexis — renda tributável e alocação (além da aula)","note":"Peça uma frase de registro formal com cada item.","items":[
   {"q":"to book a cost","a":"contabilizar um custo"},{"q":"to recognise revenue","a":"reconhecer receita"},
   {"q":"economic substance","a":"substância econômica"},{"q":"to apportion a fee","a":"ratear uma taxa"},
   {"q":"an allowable deduction","a":"uma dedução permitida"},{"q":"to align form with substance","a":"alinhar forma e substância"},
   {"q":"the taxable base","a":"a base tributável"},{"q":"to push the boundary","a":"forçar o limite"},
   {"q":"a defensible allocation","a":"uma alocação defensável"},{"q":"to bear the corresponding risk","a":"suportar o risco correspondente"}]},
 {"title":"Discuss / Argue — passiva formal no seu trabalho","note":"Respostas-modelo C1–C2 que o aluno adapta.","items":[
   {"q":"How do you decide where costs and revenue should sit across the group?","a":"Costs are booked where they make genuine economic sense and revenue is recognised by the entity that earns it, so that form and substance remain aligned."},
   {"q":"Where do you draw the line between sound and aggressive planning?","a":"Deductions are claimed only where they are genuinely supported by substance; the moment a structure is driven solely by tax, that boundary has, in my view, been crossed."},
   {"q":"How do you defend your profit allocation to an auditor?","a":"Profit is attributed to the entity that bears the corresponding risk, and because the allocation tracks economic reality, it is straightforward to defend."},
   {"q":"Why prefer the passive in tax memos?","a":"In tax communication, the impersonal passive — 'revenue is recognised', 'costs are allocated' — foregrounds the principle rather than the actor, which is precisely what a defensible memo requires."},
   {"q":"How do allowable deductions shape your effective rate?","a":"The effective rate is reduced through the application of allowable deductions, but only where each is underpinned by genuine economic substance."},
   {"q":"What makes an allocation defensible under transfer-pricing scrutiny?","a":"An allocation is defensible when value and risk are attributed to the same entity, for it is the divergence of the two that most readily attracts challenge."}]}
]

