data["469"] = [
 {"title":"Open cloze (avançado) — Condicional perfeito (terceira condicional) (fiscal-taxes)","note":"Sem opções. O aluno produz o elemento que falta.","items":[
   {"q":"Had we kept the central register, the missed credit ___ have paid for the whole team.","a":"would"},
   {"q":"If the R&D claim had been filed on time, we ___ not have forfeited the relief.","a":"would"},
   {"q":"Had the exemption ___ claimed correctly, the assessment would never have arisen.","a":"been"},
   {"q":"We would have captured the deduction ___ the documentation had been refreshed.","a":"if / had"},
   {"q":"Had the team ___ the entitlement systematically, no value would have been left on the table.","a":"tracked / pursued"},
   {"q":"The penalty would not have accrued ___ we had escalated the issue earlier.","a":"if / had"},
   {"q":"Had we treated the matter as ad-hoc, the saving ___ have been lost entirely.","a":"would"},
   {"q":"If the register ___ been maintained, the credit would have flowed automatically.","a":"had"},
   {"q":"Had they ___ aware of the exemption, they would have structured the deal differently.","a":"been"},
   {"q":"We ___ have avoided the reassessment had the position been documented at the outset.","a":"would / could"}]},
 {"title":"Key word transformation — para o condicional perfeito (terceira condicional)","note":"Reescreva usando a palavra-chave (3–6 palavras).","items":[
   {"q":"We didn't keep the register, so we missed the credit.  ·  (HAD)  ·  ___ the register, we would not have missed the credit.","a":"Had we kept"},
   {"q":"We escalated late, so the penalty accrued.  ·  (ESCALATED)  ·  Had we ___ earlier, the penalty would not have accrued.","a":"escalated the issue"},
   {"q":"The claim wasn't filed on time, so we lost the relief.  ·  (FILED)  ·  Had the claim ___ on time, we would not have lost the relief.","a":"been filed"},
   {"q":"We treated it ad-hoc, so the saving was lost.  ·  (SYSTEMATICALLY)  ·  Had we ___ , the saving would have been captured.","a":"treated it systematically"},
   {"q":"The documentation wasn't refreshed, so the deduction failed.  ·  (REFRESHED)  ·  Had the documentation ___ , the deduction would have held.","a":"been refreshed"},
   {"q":"They didn't know about the exemption, so they structured it badly.  ·  (AWARE)  ·  Had they ___ , they would have structured it well.","a":"been aware of it"}]},
 {"title":"Register / paraphrase — eleve ao registro executivo (terceira condicional)","note":"Reescreva em registro formal com inversão condicional (Had + sujeito).","items":[
   {"q":"We didn't keep a register, so we lost a credit that would've funded the team.","a":"Had we maintained a central register, the missed credit would have funded the entire team."},
   {"q":"If we'd filed the R&D claim earlier, we wouldn't have lost the relief.","a":"Had the R&D claim been filed within the window, the relief would not have been forfeited."},
   {"q":"We dealt with it on the fly, and that cost us the saving.","a":"Had the matter been handled systematically rather than ad-hoc, the saving would have been preserved."},
   {"q":"We escalated too late, so the penalty built up.","a":"Had the issue been escalated promptly, the penalty would never have accrued."},
   {"q":"They didn't realise the exemption existed, so the structure was wrong.","a":"Had they been aware of the exemption, the transaction would have been structured to capture it."},
   {"q":"We didn't document it at the start, so we got reassessed.","a":"Had the position been documented at the outset, the reassessment would have been avoided."}]},
 {"title":"Error correction (editing) — ache e corrija o erro sutil (terceira condicional)","note":"Um erro de C1/C2 por frase. Corrija e diga por quê.","items":[
   {"q":"Had we kept the register, the credit would paid for the team.","a":"Had we kept the register, the credit would have paid for the team. (condicional perfeito: 'would have' + particípio)"},
   {"q":"If we would have filed on time, we wouldn't have lost the relief.","a":"If we had filed on time, we wouldn't have lost the relief. (a oração-'if' usa 'had filed', não 'would have')"},
   {"q":"Had the claim filed on time, the relief would have held.","a":"Had the claim been filed on time, the relief would have held. (passiva exige 'been filed')"},
   {"q":"Had we treated it systematically, the saving would be captured.","a":"Had we treated it systematically, the saving would have been captured. (resultado no passado: 'would have been')"},
   {"q":"The penalty would not have accrued unless we had escalated earlier.","a":"The penalty would not have accrued had we escalated earlier. ('unless' inverte o sentido; aqui cabe 'had we / if we had')"},
   {"q":"Had they been aware the exemption, they would have used it.","a":"Had they been aware of the exemption, they would have used it. (colocação: 'aware of')"}]},
 {"title":"Advanced collocations & lexis — deduções, créditos e arrependimentos (além da aula)","note":"Peça uma frase de registro formal com cada item.","items":[
   {"q":"to forfeit a relief","a":"perder/decair de um benefício"},{"q":"to leave value on the table","a":"deixar valor na mesa"},
   {"q":"to capture a credit","a":"capturar um crédito"},{"q":"with the benefit of hindsight","a":"em retrospecto"},
   {"q":"a missed entitlement","a":"um direito não exercido"},{"q":"to fall outside the window","a":"ficar fora do prazo"},
   {"q":"to maintain a central register","a":"manter um registro central"},{"q":"a costly oversight","a":"um descuido caro"},
   {"q":"to claim systematically","a":"pleitear de forma sistemática"},{"q":"the highest-return discipline","a":"a disciplina de maior retorno"}]},
 {"title":"Discuss / Argue — condicional perfeito no seu trabalho","note":"Respostas-modelo C1–C2 que o aluno adapta.","items":[
   {"q":"Describe a tax saving your team missed and what would have prevented it.","a":"Had we maintained a single central register of entitlements, the credit we forfeited would have funded the entire team — a costly lesson in the value of unglamorous discipline."},
   {"q":"Why do you favour systematic over ad-hoc claiming of reliefs?","a":"Had the entitlements been pursued systematically rather than ad-hoc, no value would have been left on the table; that, with hindsight, is the cheapest insurance we never bought."},
   {"q":"What would have changed the outcome of a reassessment you faced?","a":"Had the position been documented at the outset rather than reconstructed afterwards, the reassessment would, in all likelihood, never have arisen."},
   {"q":"How do you justify investing in dull compliance infrastructure?","a":"Dull though a register may seem, had we kept one, we would have captured reliefs whose value dwarfs the cost of maintaining it."},
   {"q":"Reflect on a deadline your team narrowly missed.","a":"Had the claim been filed even a week earlier, the relief would not have been forfeited, which is why we now treat the filing window as immovable."},
   {"q":"What advice would you give a younger tax lead about reliefs?","a":"I would tell them that, had I tracked every entitlement from the start, I would have spared myself years of retrospective firefighting."}]}
]

# ---------------------------------------------------------------------------
# 470 — Subjunctive in formal proposals
# ---------------------------------------------------------------------------
data["470"] = [
 {"title":"Open cloze (avançado) — Subjuntivo em propostas formais (fiscal-taxes)","note":"Sem opções. O aluno produz o elemento que falta.","items":[
   {"q":"I recommend that the tax director ___ the loss-utilisation policy without delay.","a":"review"},
   {"q":"The committee insists that every entity ___ aligned with group strategy.","a":"be"},
   {"q":"It is essential that the proposal ___ approved before the quarter closes.","a":"be"},
   {"q":"We propose that the team ___ involved at the earliest stage of any restructuring.","a":"be"},
   {"q":"The board requires that no position ___ taken without prior modelling.","a":"be"},
   {"q":"I suggest that he ___ the allocation across entities once more.","a":"reconsider"},
   {"q":"It is critical that the utilisation of losses ___ documented contemporaneously.","a":"be"},
   {"q":"The auditor recommended that the policy ___ revisited annually.","a":"be"},
   {"q":"We ask that each director ___ the strategic rationale in writing.","a":"set out / record"},
   {"q":"It is imperative that tax strategy ___ aligned with the direction of the business.","a":"be"}]},
 {"title":"Key word transformation — para o subjuntivo formal (subjuntivo)","note":"Reescreva usando a palavra-chave (3–6 palavras).","items":[
   {"q":"We strongly advise the director to review the policy.  ·  (RECOMMEND)  ·  We ___ the policy.","a":"recommend that he review"},
   {"q":"It's vital to approve the proposal this quarter.  ·  (ESSENTIAL)  ·  It is essential that the proposal ___ this quarter.","a":"be approved"},
   {"q":"The board won't allow any position without modelling.  ·  (REQUIRES)  ·  The board ___ without modelling.","a":"requires that no position be taken"},
   {"q":"We want the team involved early.  ·  (PROPOSE)  ·  We propose that the team ___ early.","a":"be involved"},
   {"q":"It's crucial to document the loss utilisation as it happens.  ·  (CRITICAL)  ·  It is critical that the utilisation ___ contemporaneously.","a":"be documented"},
   {"q":"He should reconsider the allocation, in my view.  ·  (SUGGEST)  ·  I suggest that he ___ the allocation.","a":"reconsider"}]},
 {"title":"Register / paraphrase — eleve ao registro executivo (subjuntivo formal)","note":"Reescreva como proposta formal usando o subjuntivo.","items":[
   {"q":"The director should really review the loss policy now.","a":"I recommend that the director review the loss-utilisation policy without delay."},
   {"q":"We can't approve anything until it's been modelled.","a":"The board requires that no proposal be approved until it has been fully modelled."},
   {"q":"Let's get the tax team in early on any restructuring.","a":"We propose that the tax team be involved at the earliest stage of any restructuring."},
   {"q":"It's really important to write down why we chose this allocation.","a":"It is essential that the rationale for the allocation be set out in writing."},
   {"q":"They want every entity lined up with the group's plan.","a":"The committee insists that every entity be aligned with group strategy."},
   {"q":"Document the loss utilisation as you go, not afterwards.","a":"It is critical that the utilisation of losses be documented contemporaneously rather than retrospectively."}]},
 {"title":"Error correction (editing) — ache e corrija o erro sutil (subjuntivo)","note":"Um erro de C1/C2 por frase. Corrija e diga por quê.","items":[
   {"q":"I recommend that he reviews the policy without delay.","a":"I recommend that he review the policy without delay. (subjuntivo usa a forma base 'review', sem -s)"},
   {"q":"It is essential that the proposal is approved this quarter.","a":"It is essential that the proposal be approved this quarter. (subjuntivo formal: 'be approved')"},
   {"q":"The board requires that no position is taken without modelling.","a":"The board requires that no position be taken without modelling. (após 'require that', subjuntivo 'be taken')"},
   {"q":"We propose that the team will be involved early.","a":"We propose that the team be involved early. (subjuntivo não usa 'will')"},
   {"q":"It is critical that the utilisation be document contemporaneously.","a":"It is critical that the utilisation be documented contemporaneously. (passiva do subjuntivo: 'be documented')"},
   {"q":"I suggest that he reconsiders the allocation once more.","a":"I suggest that he reconsider the allocation once more. (subjuntivo: forma base 'reconsider')"}]},
 {"title":"Advanced collocations & lexis — tributo corporativo como variável (além da aula)","note":"Peça uma frase de registro formal com cada item.","items":[
   {"q":"the utilisation of losses","a":"o aproveitamento de prejuízos"},{"q":"to align tax with strategy","a":"alinhar o tributo à estratégia"},
   {"q":"to model an outcome","a":"modelar um resultado"},{"q":"contemporaneous documentation","a":"documentação tempestiva"},
   {"q":"to command a premium","a":"comandar um prêmio (de valor)"},{"q":"a narrow view","a":"uma visão estreita"},
   {"q":"to reinvest at the margin","a":"reinvestir na margem"},{"q":"a stable effective rate","a":"uma alíquota efetiva estável"},
   {"q":"to set out the rationale","a":"expor a justificativa"},{"q":"a long-horizon variable","a":"uma variável de longo horizonte"}]},
 {"title":"Discuss / Argue — subjuntivo formal no seu trabalho","note":"Respostas-modelo C1–C2 que o aluno adapta.","items":[
   {"q":"What single change would you recommend to your group's tax governance?","a":"I would recommend that every restructuring be modelled for its tax consequences before, rather than after, the commercial decision is taken."},
   {"q":"How do you ensure tax is considered early in strategic decisions?","a":"I insist that the tax function be involved at the earliest stage, for it is essential that the structure be shaped while it is still malleable."},
   {"q":"Why treat corporate tax as a strategic variable rather than a cost?","a":"A stable, well-managed effective rate commands a premium with investors; accordingly, it is critical that tax strategy be aligned with the direction of the business, not bolted on afterwards."},
   {"q":"What would you require before approving an aggressive position?","a":"I would require that the position be fully modelled and contemporaneously documented, since a saving that cannot be defended is no saving at all."},
   {"q":"How do you handle loss utilisation across entities?","a":"I propose that the utilisation of losses be governed centrally and documented as it occurs, so that the rationale survives any later challenge."},
   {"q":"What advice would you give a board that views tax too narrowly?","a":"I would suggest that the board cease to regard tax as mere arithmetic and instead treat it as a long-horizon variable that shapes how the entire enterprise is valued."}]}
]

