data["471"] = [
 {"title":"Open cloze (avançado) — Orações clivadas (fiscal-taxes)","note":"Sem opções. O aluno produz o elemento que falta.","items":[
   {"q":"What matters about VAT ___ its effect on working capital, not its visibility on the P&L.","a":"is"},
   {"q":"It is the invisibility ___ VAT that makes it so easy to mismanage.","a":"of"},
   {"q":"What the reverse charge mechanism does ___ shift the accounting to the recipient.","a":"is"},
   {"q":"It is the timing of the refund ___ determines our working-capital position.","a":"that"},
   {"q":"What we recover ___ input VAT; what we charge is output VAT.","a":"is"},
   {"q":"It is ___ this gap between charging and settling that the cash engine operates.","a":"in / through"},
   {"q":"What drives the cash benefit ___ the lag between collection and remittance.","a":"is"},
   {"q":"It is the shape ___ the flow, not the headline rate, that we manage.","a":"of"},
   {"q":"What few executives appreciate ___ how much liquidity VAT timing can release.","a":"is"},
   {"q":"It is registration in the right jurisdictions ___ unlocks the recovery.","a":"that"}]},
 {"title":"Key word transformation — destaque por clivagem (cleft)","note":"Reescreva usando a palavra-chave (3–6 palavras).","items":[
   {"q":"VAT timing affects working capital most.  ·  (IT)  ·  ___ affects working capital most.","a":"It is VAT timing that"},
   {"q":"The invisibility of VAT makes it easy to mismanage.  ·  (IT)  ·  ___ makes it easy to mismanage.","a":"It is the invisibility of VAT that"},
   {"q":"We recover input VAT.  ·  (WHAT)  ·  ___ is input VAT.","a":"What we recover"},
   {"q":"The lag between collection and remittance drives the benefit.  ·  (IT)  ·  ___ drives the benefit.","a":"It is the lag that"},
   {"q":"Few executives appreciate how much liquidity VAT releases.  ·  (WHAT)  ·  ___ appreciate is how much liquidity VAT releases.","a":"What few executives"},
   {"q":"Registration in the right places unlocks the recovery.  ·  (IT)  ·  ___ unlocks the recovery.","a":"It is registration that"}]},
 {"title":"Register / paraphrase — eleve ao registro executivo (cleft)","note":"Reescreva em registro formal usando cleft.","items":[
   {"q":"VAT timing is the thing that really affects our cash.","a":"It is the timing of VAT, rather than the rate, that genuinely affects our cash position."},
   {"q":"People mismanage VAT because they can't see it.","a":"It is the very invisibility of VAT that makes it so prone to mismanagement."},
   {"q":"We recover the VAT we paid and charge the VAT we collect.","a":"What we recover is input VAT; what we charge is output VAT."},
   {"q":"The gap between charging and paying is where the cash benefit comes from.","a":"It is in the gap between charging and settling that the cash engine operates."},
   {"q":"Most executives don't realise how much liquidity good VAT timing frees up.","a":"What most executives fail to appreciate is the liquidity that disciplined VAT timing can release."},
   {"q":"Registering in the right places is what lets us recover the VAT.","a":"It is registration in the right jurisdictions that unlocks the recovery of input VAT."}]},
 {"title":"Error correction (editing) — ache e corrija o erro sutil (cleft)","note":"Um erro de C1/C2 por frase. Corrija e diga por quê.","items":[
   {"q":"It is the invisibility of VAT what makes it easy to mismanage.","a":"It is the invisibility of VAT that makes it easy to mismanage. (cleft com 'it is' usa 'that')"},
   {"q":"What we recover are input VAT.","a":"What we recover is input VAT. (cleft com 'what' rege verbo singular 'is')"},
   {"q":"It is the timing of the refund which determines our position, isn't it.","a":"It is the timing of the refund that determines our position. (sem question tag no registro formal; prefere-se 'that')"},
   {"q":"What the reverse charge does is shifts the accounting.","a":"What the reverse charge does is shift the accounting. (após 'does is' usa-se a forma base 'shift')"},
   {"q":"It is in the gap between charging and settle that the engine operates.","a":"It is in the gap between charging and settling that the engine operates. (paralelismo de gerúndios: 'charging and settling')"},
   {"q":"What few executives appreciates is the liquidity released.","a":"What few executives appreciate is the liquidity released. (sujeito plural 'executives' exige 'appreciate')"}]},
 {"title":"Advanced collocations & lexis — VAT como motor de caixa (além da aula)","note":"Peça uma frase de registro formal com cada item.","items":[
   {"q":"to recover input VAT","a":"recuperar o VAT pago"},{"q":"the reverse charge mechanism","a":"o mecanismo de inversão do sujeito passivo"},
   {"q":"working-capital benefit","a":"benefício de capital de giro"},{"q":"to bridge the timing gap","a":"cobrir a defasagem temporal"},
   {"q":"a cash-flow lag","a":"uma defasagem de fluxo de caixa"},{"q":"to accelerate a refund","a":"acelerar um reembolso"},
   {"q":"output versus input VAT","a":"VAT a recolher versus a recuperar"},{"q":"to release liquidity","a":"liberar liquidez"},
   {"q":"the filing cycle","a":"o ciclo de declaração"},{"q":"an overpayment position","a":"uma posição de pagamento a maior"}]},
 {"title":"Discuss / Argue — clivagem e VAT no seu trabalho","note":"Respostas-modelo C1–C2 que o aluno adapta.","items":[
   {"q":"Why do you describe VAT as a cash engine rather than a tax?","a":"It is the timing of VAT, not its rate, that matters most to a trader: managed well, the lag between charging and settling becomes a genuine source of working capital."},
   {"q":"What do executives most often miss about VAT?","a":"What most executives fail to appreciate is the liquidity that disciplined VAT timing can release, precisely because the tax is invisible on the income statement."},
   {"q":"How does the reverse charge mechanism change your accounting?","a":"What the reverse charge does is shift the accounting obligation to the recipient, which, for cross-border sugar flows, materially simplifies our compliance."},
   {"q":"Why is registration strategy so important for VAT recovery?","a":"It is registration in the right jurisdictions that unlocks the recovery of input VAT; without it, real cash is simply left stranded in the supply chain."},
   {"q":"How do you turn the VAT filing cycle to the firm's advantage?","a":"It is in the gap between collection and remittance that the cash engine operates, so we structure the filing cycle to extend that gap wherever it is legally permitted."},
   {"q":"What is the risk of treating VAT as merely administrative?","a":"It is the invisibility of VAT that makes it so easy to mismanage, and a firm that treats it as clerical routinely strands liquidity it could have deployed."}]}
]

