data["472"] = [
 {"title":"Open cloze (avançado) — Passiva com modais na governança documental (fiscal-taxes)","note":"Sem opções. O aluno produz o elemento que falta.","items":[
   {"q":"Invoices must ___ checked automatically against the intake checklist.","a":"be"},
   {"q":"Problem invoices should ___ routed out before they reach the ledger.","a":"be"},
   {"q":"Records must ___ retained for the full statutory period in every jurisdiction.","a":"be"},
   {"q":"Incomplete documents ought to ___ escalated rather than quietly corrected.","a":"be"},
   {"q":"No invoice can ___ posted until it has passed the automated check.","a":"be"},
   {"q":"The retention policy must ___ applied consistently across all entities.","a":"be"},
   {"q":"Every exception should ___ logged so that the pattern can ___ analysed.","a":"be ... be"},
   {"q":"Documentation has to ___ governed as a control, not treated as a clerical task.","a":"be"},
   {"q":"Sensitive records may not ___ destroyed before the retention window expires.","a":"be"},
   {"q":"The intake checklist ought to ___ reviewed whenever the rules change.","a":"be"}]},
 {"title":"Key word transformation — para a passiva com modal (passiva + modais)","note":"Reescreva usando a palavra-chave (3–6 palavras).","items":[
   {"q":"We must check every invoice automatically.  ·  (CHECKED)  ·  Every invoice must ___ automatically.","a":"be checked"},
   {"q":"You should route problem invoices out early.  ·  (ROUTED)  ·  Problem invoices should ___ out early.","a":"be routed"},
   {"q":"We have to retain records for the full period.  ·  (RETAINED)  ·  Records have to ___ for the full period.","a":"be retained"},
   {"q":"Nobody may destroy records before the window ends.  ·  (DESTROYED)  ·  Records may not ___ before the window ends.","a":"be destroyed"},
   {"q":"We ought to log every exception.  ·  (LOGGED)  ·  Every exception ought to ___ .","a":"be logged"},
   {"q":"You can't post an invoice until it passes the check.  ·  (POSTED)  ·  No invoice can ___ until it passes the check.","a":"be posted"}]},
 {"title":"Register / paraphrase — eleve ao registro executivo (passiva + modais)","note":"Reescreva em registro formal usando passiva com modal.","items":[
   {"q":"We need the system to check every invoice automatically.","a":"Every invoice must be checked automatically against the intake checklist."},
   {"q":"Get the bad invoices out before they hit the ledger.","a":"Problem invoices should be routed out before they are posted to the ledger."},
   {"q":"Keep the records for as long as the law says, everywhere.","a":"Records must be retained for the full statutory period in every jurisdiction."},
   {"q":"Don't let anyone shred records too early.","a":"Records may not be destroyed before the retention window has expired."},
   {"q":"Log all the exceptions so we can see the pattern.","a":"Every exception should be logged so that the underlying pattern can be analysed."},
   {"q":"Treat documentation as a real control, not admin.","a":"Documentation must be governed as a control rather than treated as a clerical task."}]},
 {"title":"Error correction (editing) — ache e corrija o erro sutil (passiva + modais)","note":"Um erro de C1/C2 por frase. Corrija e diga por quê.","items":[
   {"q":"Invoices must checked automatically.","a":"Invoices must be checked automatically. (passiva com modal exige 'be' + particípio)"},
   {"q":"Records must be retain for the statutory period.","a":"Records must be retained for the statutory period. (particípio 'retained')"},
   {"q":"No invoice can be post until it passes the check.","a":"No invoice can be posted until it passes the check. (particípio 'posted')"},
   {"q":"Sensitive records may not be destroy before the window expires.","a":"Sensitive records may not be destroyed before the window expires. (particípio 'destroyed')"},
   {"q":"Every exception should be log so the pattern can be analyse.","a":"Every exception should be logged so the pattern can be analysed. (ambos exigem particípio: 'logged', 'analysed')"},
   {"q":"Documentation must to be governed as a control.","a":"Documentation must be governed as a control. (modal 'must' não leva 'to')"}]},
 {"title":"Advanced collocations & lexis — governança de faturas e documentos (além da aula)","note":"Peça uma frase de registro formal com cada item.","items":[
   {"q":"an intake checklist","a":"um checklist de entrada"},{"q":"to route out an exception","a":"desviar/segregar uma exceção"},
   {"q":"a retention period","a":"um período de retenção"},{"q":"to post to the ledger","a":"lançar no razão"},
   {"q":"an automated control","a":"um controle automatizado"},{"q":"to flag a discrepancy","a":"sinalizar uma divergência"},
   {"q":"an audit-ready record","a":"um registro pronto para auditoria"},{"q":"to embed a control","a":"incorporar um controle"},
   {"q":"a clean data trail","a":"uma trilha de dados limpa"},{"q":"to govern by exception","a":"gerir por exceção"}]},
 {"title":"Discuss / Argue — governança documental no seu trabalho","note":"Respostas-modelo C1–C2 que o aluno adapta.","items":[
   {"q":"How should invoice quality be controlled at enterprise scale?","a":"Every invoice must be checked automatically at intake, and any that is incomplete should be routed out before it is ever posted to the ledger."},
   {"q":"Why treat documentation as a control rather than admin?","a":"Documentation must be governed as a genuine control, for it is on the quality of the record, not the elegance of the position, that any audit ultimately turns."},
   {"q":"How do you handle exceptions in your documentation flow?","a":"Every exception should be logged rather than quietly corrected, so that the pattern can be analysed and the underlying weakness addressed."},
   {"q":"What is your policy on record retention across jurisdictions?","a":"Records must be retained for the full statutory period in each jurisdiction and may not be destroyed until the relevant window has expired."},
   {"q":"Why does patient design of controls pay off?","a":"Controls that are designed patiently and embedded early mean that, when the auditor arrives, nothing needs to be reconstructed because everything was captured correctly the first time."},
   {"q":"How do automated checks change the auditor relationship?","a":"Where every invoice has already been validated automatically, the auditor's work shifts from reconstruction to confirmation, which materially shortens and de-risks the engagement."}]}
]

