# ---------------------------------------------------------------------------
data["473"] = [
 {"title":"Open cloze (avançado) — Orações subordinadas formais (fiscal-taxes)","note":"Sem opções. O aluno produz o elemento que falta.","items":[
   {"q":"___ that the CEO welcomes questions, the rest of the organisation learns to raise them.","a":"Provided"},
   {"q":"To the ___ that compliance is seen as a burden, people will quietly bury their doubts.","a":"extent"},
   {"q":"___ the tone at the top is impatient, even valid concerns go unspoken.","a":"Where / When / If"},
   {"q":"Compliance culture takes root only ___ leaders respond to doubt with genuine patience.","a":"when / if / where"},
   {"q":"___ the rules are complex, a culture of questioning matters more, not less.","a":"Although / Even though"},
   {"q":"Concerns surface ___ long as people believe they will be heard calmly.","a":"as / so"},
   {"q":"___ a director sighs at a question, a precedent of silence is set.","a":"Once / When / If"},
   {"q":"Tax risk is contained ___ that issues are raised early and addressed directly.","a":"provided / on condition"},
   {"q":"The culture endures ___ it is modelled deliberately from the top.","a":"insofar as / provided / so long as"},
   {"q":"___ deliberately the tone is set, the more reliably concerns are surfaced.","a":"The more"}]},
 {"title":"Key word transformation — subordine formalmente (orações formais)","note":"Reescreva usando a palavra-chave (3–6 palavras).","items":[
   {"q":"If the CEO welcomes questions, people raise them.  ·  (PROVIDED)  ·  ___ , people raise them.","a":"Provided the CEO welcomes questions"},
   {"q":"Compliance is partly a burden, and to that degree people stay quiet.  ·  (EXTENT)  ·  To the ___ , people stay quiet.","a":"extent that compliance is a burden"},
   {"q":"Even with complex rules, a questioning culture matters more.  ·  (ALTHOUGH)  ·  ___ , a questioning culture matters more.","a":"Although the rules are complex"},
   {"q":"Concerns surface only if people feel heard.  ·  (PROVIDED)  ·  Concerns surface ___ heard.","a":"provided people feel"},
   {"q":"When a director sighs, silence becomes the norm.  ·  (ONCE)  ·  ___ , silence becomes the norm.","a":"Once a director sighs"},
   {"q":"The culture lasts because it is modelled from the top.  ·  (INSOFAR)  ·  The culture lasts ___ from the top.","a":"insofar as it is modelled"}]},
 {"title":"Register / paraphrase — eleve ao registro executivo (orações subordinadas)","note":"Reescreva em registro formal usando conectores subordinativos.","items":[
   {"q":"If the boss is open to questions, everyone else opens up too.","a":"Provided that the CEO welcomes questions, the rest of the organisation learns to raise them."},
   {"q":"If people think compliance is just a hassle, they'll hide their doubts.","a":"To the extent that compliance is perceived as a burden, doubts will quietly be buried."},
   {"q":"The rules are complicated, but that makes a questioning culture even more important.","a":"Although the rules are complex, a culture of questioning becomes more important, not less."},
   {"q":"As long as people feel they'll be heard, they'll speak up.","a":"So long as people believe they will be heard calmly, concerns will continue to surface."},
   {"q":"Once a director rolls their eyes at a question, no one asks again.","a":"Once a director responds to a question with visible impatience, a precedent of silence is set."},
   {"q":"The culture only lasts if leaders keep modelling it.","a":"The culture endures only insofar as it is deliberately modelled from the top."}]},
 {"title":"Error correction (editing) — ache e corrija o erro sutil (orações formais)","note":"Um erro de C1/C2 por frase. Corrija e diga por quê.","items":[
   {"q":"Provided that the CEO will welcome questions, people raise them.","a":"Provided that the CEO welcomes questions, people raise them. (após 'provided that' usa-se presente, não 'will')"},
   {"q":"To the extent of compliance is a burden, doubts are buried.","a":"To the extent that compliance is a burden, doubts are buried. (o conector é 'to the extent that')"},
   {"q":"Although the rules are complex, but a questioning culture matters more.","a":"Although the rules are complex, a questioning culture matters more. ('although' e 'but' não se usam juntos)"},
   {"q":"Concerns surface so long that people feel heard.","a":"Concerns surface so long as people feel heard. (o conector correto é 'so long as')"},
   {"q":"The culture endures insofar it is modelled from the top.","a":"The culture endures insofar as it is modelled from the top. (a forma é 'insofar as')"},
   {"q":"Once a director will sigh, silence becomes the norm.","a":"Once a director sighs, silence becomes the norm. (oração temporal usa presente, não 'will')"}]},
 {"title":"Advanced collocations & lexis — cultura de conformidade no topo (além da aula)","note":"Peça uma frase de registro formal com cada item.","items":[
   {"q":"to set the tone at the top","a":"definir o tom a partir do topo"},{"q":"to surface a concern","a":"trazer à tona uma preocupação"},
   {"q":"to bury a doubt","a":"enterrar uma dúvida"},{"q":"a speak-up culture","a":"uma cultura de manifestação"},
   {"q":"to model behaviour deliberately","a":"modelar comportamento deliberadamente"},{"q":"a precedent of silence","a":"um precedente de silêncio"},
   {"q":"to respond with genuine patience","a":"responder com paciência genuína"},{"q":"to embed a culture","a":"enraizar uma cultura"},
   {"q":"psychological safety","a":"segurança psicológica"},{"q":"to chill dissent","a":"inibir a discordância"}]},
 {"title":"Discuss / Argue — cultura de conformidade no seu trabalho","note":"Respostas-modelo C1–C2 que o aluno adapta.","items":[
   {"q":"How does a compliance culture actually begin?","a":"Provided that those at the top welcome difficult questions and respond to them with genuine patience, the rest of the organisation gradually learns to raise its own."},
   {"q":"Why can a single impatient reaction be so damaging?","a":"Once a senior figure responds to a concern with visible impatience, a precedent of silence is set, and to the extent that silence spreads, real risks go unreported."},
   {"q":"Do complex rules weaken or strengthen the case for a speak-up culture?","a":"Although the rules are complex, a questioning culture matters more, not less, precisely because complexity is where unexamined assumptions tend to hide."},
   {"q":"How do you keep a compliance culture alive over time?","a":"The culture endures only insofar as it is modelled deliberately and repeatedly from the top; left to itself, it quietly decays into box-ticking."},
   {"q":"What signals to your team that doubts are genuinely welcome?","a":"So long as every concern, however inconvenient, is met calmly and addressed directly, people come to believe that speaking up carries no penalty."},
   {"q":"How would you rebuild a culture where people had learned to stay quiet?","a":"To the extent that silence has become habitual, it must be reversed deliberately — by visibly rewarding the very questions that were previously sighed at."}]}
]

