data["474"] = [
 {"title":"Open cloze (avançado) — Condicional perfeito e passiva complexa (fiscal-taxes)","note":"Sem opções. O aluno produz o elemento que falta.","items":[
   {"q":"Had the borderline positions not ___ resolved early, they would have become material problems.","a":"been"},
   {"q":"If the issues had not been triaged, the penalties ___ have accumulated unchecked.","a":"would"},
   {"q":"Had the narrative ___ documented contemporaneously, the audit would have closed sooner.","a":"been"},
   {"q":"The exposure would have been contained ___ each position had been classified at the outset.","a":"if / had"},
   {"q":"Had the matter been ___ to the executive committee, a decision would have been taken in time.","a":"escalated / referred"},
   {"q":"If the risk had ___ documented, it could have been defended without difficulty.","a":"been"},
   {"q":"Had the positions been ___ by risk, resources would have been allocated correctly.","a":"classified / ranked"},
   {"q":"The penalty would not have ___ assessed had the disclosure been made voluntarily.","a":"been"},
   {"q":"Had the controls been ___ properly, the discrepancy would have been caught earlier.","a":"designed / applied"},
   {"q":"If the triage had been ___ out monthly, no problem would have been allowed to accumulate.","a":"carried"}]},
 {"title":"Key word transformation — condicional perfeito + passiva (estrutura combinada)","note":"Reescreva usando a palavra-chave (3–6 palavras).","items":[
   {"q":"We resolved the positions early, so they didn't become problems.  ·  (HAD)  ·  ___ early, they would have become problems.","a":"Had they not been resolved"},
   {"q":"Nobody documented the narrative, so the audit dragged on.  ·  (DOCUMENTED)  ·  Had the narrative ___ , the audit would have closed sooner.","a":"been documented"},
   {"q":"We classified each position, so resources were well allocated.  ·  (CLASSIFIED)  ·  Had the positions not ___ , resources would have been misallocated.","a":"been classified"},
   {"q":"We disclosed voluntarily, so no penalty was assessed.  ·  (DISCLOSED)  ·  Had the matter not ___ voluntarily, a penalty would have been assessed.","a":"been disclosed"},
   {"q":"We escalated to the committee, so a decision came in time.  ·  (ESCALATED)  ·  Had the matter not ___ , no decision would have been taken in time.","a":"been escalated"},
   {"q":"We ran triage monthly, so nothing accumulated.  ·  (CARRIED)  ·  Had triage not ___ monthly, problems would have accumulated.","a":"been carried out"}]},
 {"title":"Register / paraphrase — eleve ao registro executivo (condicional + passiva)","note":"Reescreva em registro formal com inversão condicional e passiva.","items":[
   {"q":"We sorted the risky positions early, otherwise they'd have blown up.","a":"Had the borderline positions not been resolved early, they would have become material problems."},
   {"q":"Nobody wrote down the story, so the audit took forever.","a":"Had the narrative been documented contemporaneously, the audit would have closed far sooner."},
   {"q":"We came clean first, so they didn't fine us.","a":"Had the disclosure not been made voluntarily, a penalty would almost certainly have been assessed."},
   {"q":"We ranked everything by risk, so we put resources in the right place.","a":"Had the positions not been classified by risk, resources would have been misallocated entirely."},
   {"q":"We took it to the committee in time, so they could decide.","a":"Had the matter not been escalated to the committee, no timely decision could have been taken."},
   {"q":"We did triage every month, so nothing piled up.","a":"Had triage not been carried out monthly, the issues would have been allowed to accumulate unchecked."}]},
 {"title":"Error correction (editing) — ache e corrija o erro sutil (condicional + passiva)","note":"Um erro de C1/C2 por frase. Corrija e diga por quê.","items":[
   {"q":"Had the positions not resolved early, they would have become problems.","a":"Had the positions not been resolved early, they would have become problems. (passiva exige 'been resolved')"},
   {"q":"If the narrative had documented, the audit would have closed sooner.","a":"If the narrative had been documented, the audit would have closed sooner. (passiva: 'had been documented')"},
   {"q":"The penalty would not have been assess had we disclosed.","a":"The penalty would not have been assessed had we disclosed. (particípio 'assessed')"},
   {"q":"Had the matter been escalated, a decision would be taken in time.","a":"Had the matter been escalated, a decision would have been taken in time. (resultado passado: 'would have been taken')"},
   {"q":"Had triage carried out monthly, nothing would have accumulated.","a":"Had triage been carried out monthly, nothing would have accumulated. (passiva: 'been carried out')"},
   {"q":"If the controls had been design properly, the error would have been caught.","a":"If the controls had been designed properly, the error would have been caught. (particípio 'designed')"}]},
 {"title":"Advanced collocations & lexis — gestão de risco e multas (além da aula)","note":"Peça uma frase de registro formal com cada item.","items":[
   {"q":"to triage by risk","a":"triar por risco"},{"q":"a borderline position","a":"uma posição limítrofe"},
   {"q":"to accumulate unchecked","a":"acumular-se sem controle"},{"q":"to make a voluntary disclosure","a":"fazer uma divulgação voluntária"},
   {"q":"to contain an exposure","a":"conter uma exposição"},{"q":"a material problem","a":"um problema relevante"},
   {"q":"to assess a penalty","a":"aplicar uma multa"},{"q":"to build the narrative","a":"construir a narrativa (de defesa)"},
   {"q":"to escalate to the executive committee","a":"escalar ao comitê executivo"},{"q":"unglamorous triage","a":"triagem sem glamour"}]},
 {"title":"Discuss / Argue — risco e multas no seu trabalho","note":"Respostas-modelo C1–C2 que o aluno adapta.","items":[
   {"q":"Describe how early triage prevented a serious problem.","a":"Had the borderline positions not been triaged and resolved early, they would have accumulated unchecked into a material exposure that no narrative could later have explained away."},
   {"q":"Why do you insist on contemporaneous documentation of risk positions?","a":"Had the rationale been documented as the position was taken rather than reconstructed afterwards, the audit would have closed far sooner and the penalty would never have been assessed."},
   {"q":"When is a voluntary disclosure the right call?","a":"Where an error is material, a voluntary disclosure is almost always warranted, for had we waited to be found, the penalty would have been assessed at a far harsher rate."},
   {"q":"How do you allocate scarce resources across many risk positions?","a":"Positions must first be classified by risk; had we not done so, resources would have been spread evenly and the genuinely dangerous items would have been under-resourced."},
   {"q":"Defend the value of 'unglamorous triage' to a sceptical board.","a":"Triage is unglamorous, yet had it not been carried out month after month, small borderline issues would have compounded into the very crises the board most fears."},
   {"q":"What is your motto for penalty management?","a":"Resolve early, document as you go: had we lived by anything else, half our closed matters would still be open and contested."}]}
]

# ---------------------------------------------------------------------------
# 475 — Rhetorical closing devices
# ---------------------------------------------------------------------------
data["475"] = [
 {"title":"Open cloze (avançado) — Recursos retóricos de fechamento (fiscal-taxes)","note":"Sem opções. O aluno produz o elemento que falta.","items":[
   {"q":"Remove the calendar, ___ emergencies flood in; protect it, and they simply stop happening.","a":"and"},
   {"q":"Plan early, file on time, ___ sleep at night.","a":"and"},
   {"q":"The rhythm is not glamorous, ___ it is what keeps the whole function calm.","a":"but"},
   {"q":"Predictability hardens into routine, routine into discipline, ___ discipline into trust.","a":"and"},
   {"q":"It is not the size of the team that protects us; ___ is the steadiness of the rhythm.","a":"it"},
   {"q":"Set the pace, hold the pace, ___ the year takes care of itself.","a":"and"},
   {"q":"Lose the preparation window, ___ every deadline becomes a crisis.","a":"and"},
   {"q":"Patient leadership is quiet, unhurried, ___ — in the end — decisive.","a":"and"},
   {"q":"What the calendar gives us is not merely order ___ peace of mind.","a":"but"},
   {"q":"Protect the rhythm, ___ the rhythm will protect you.","a":"and"}]},
 {"title":"Key word transformation — feche com efeito retórico (tríades e contrastes)","note":"Reescreva usando a palavra-chave (3–6 palavras).","items":[
   {"q":"If you remove the calendar, emergencies flood in.  ·  (AND)  ·  Remove the calendar, ___ in.","a":"and emergencies flood"},
   {"q":"What protects us is the steadiness, not the size of the team.  ·  (IT)  ·  ___ that protects us.","a":"It is the steadiness"},
   {"q":"The rhythm is unglamorous, yet it keeps everyone calm.  ·  (BUT)  ·  The rhythm is unglamorous, ___ calm.","a":"but it keeps everyone"},
   {"q":"Predictability becomes routine, which becomes discipline.  ·  (INTO)  ·  Predictability hardens ___ discipline.","a":"into routine and then"},
   {"q":"If you protect the rhythm, it will protect you.  ·  (AND)  ·  Protect the rhythm, ___ you.","a":"and it will protect"},
   {"q":"The calendar gives order and, more than that, peace of mind.  ·  (NOT MERELY)  ·  The calendar gives ___ peace of mind.","a":"not merely order but"}]},
 {"title":"Register / paraphrase — eleve ao registro executivo (fechamento retórico)","note":"Reescreva como fechamento executivo usando tríade, contraste ou paralelo.","items":[
   {"q":"If we lose the prep window, everything becomes an emergency.","a":"Lose the preparation window, and every deadline becomes a crisis; protect it, and the crises simply stop happening."},
   {"q":"The calendar isn't exciting but it keeps us calm.","a":"The rhythm is not glamorous, but it is precisely what keeps the entire function calm."},
   {"q":"Being predictable becomes a habit, then a discipline, then trust.","a":"Predictability hardens into routine, routine into discipline, and discipline, in time, into trust."},
   {"q":"It's not how big the team is, it's how steady we are.","a":"It is not the size of the team that protects us; it is the steadiness of the rhythm."},
   {"q":"If you look after the calendar, it looks after you.","a":"Protect the rhythm, and the rhythm, in turn, will protect you."},
   {"q":"Good leadership here is quiet and patient but it gets results.","a":"Patient leadership is quiet, unhurried and — in the end — decisive."}]},
 {"title":"Error correction (editing) — ache e corrija o erro sutil (fechamento retórico)","note":"Um erro de C1/C2 por frase. Corrija e diga por quê.","items":[
   {"q":"Remove the calendar and emergencies floods in.","a":"Remove the calendar, and emergencies flood in. (sujeito plural 'emergencies' exige 'flood'; vírgula antes de 'and' marca a construção imperativa)"},
   {"q":"It is not the size of the team what protects us.","a":"It is not the size of the team that protects us. (cleft usa 'that', não 'what')"},
   {"q":"Predictability hardens into routine, discipline and trust, isn't it.","a":"Predictability hardens into routine, discipline and trust. (fechamento formal dispensa a question tag)"},
   {"q":"The rhythm is unglamorous, but however it keeps us calm.","a":"The rhythm is unglamorous, but it keeps us calm. ('but' e 'however' redundantes juntos)"},
   {"q":"Protect the rhythm and the rhythm protect you.","a":"Protect the rhythm, and the rhythm will protect you. (futuro 'will protect' para o efeito condicional)"},
   {"q":"Patient leadership is quiet, unhurried, decisive in the end and so on.","a":"Patient leadership is quiet, unhurried and, in the end, decisive. (a tríade fecha com efeito; 'and so on' enfraquece o registro)"}]},
 {"title":"Advanced collocations & lexis — calendário e ritmo fiscal (além da aula)","note":"Peça uma frase de registro formal com cada item.","items":[
   {"q":"to set the pace","a":"ditar o ritmo"},{"q":"a preparation window","a":"uma janela de preparação"},
   {"q":"to harden into routine","a":"consolidar-se em rotina"},{"q":"crunch time","a":"hora da verdade / reta final"},
   {"q":"to stay ahead of the deadline","a":"antecipar-se ao prazo"},{"q":"predictability breeds calm","a":"a previsibilidade gera tranquilidade"},
   {"q":"to absorb a shock","a":"absorver um choque"},{"q":"a filing cadence","a":"uma cadência de declarações"},
   {"q":"to take the heat out of a deadline","a":"tirar a pressão de um prazo"},{"q":"quiet competence","a":"competência silenciosa"}]},
 {"title":"Discuss / Argue — ritmo e calendário no seu trabalho","note":"Respostas-modelo C1–C2 que o aluno adapta.","items":[
   {"q":"Why do you describe the tax calendar as a rhythm rather than a list of dates?","a":"A list of dates merely records deadlines; a rhythm sets the pace for the whole function — protect it, and the crises simply stop happening."},
   {"q":"How does predictability translate into trust?","a":"Predictability hardens into routine, routine into discipline, and discipline, over the years, into the quiet trust that lets the board stop worrying about us."},
   {"q":"What protects a finance function more — size or steadiness?","a":"It is not the size of the team that protects us; it is the steadiness of the rhythm, for a small, well-paced team will always outperform a large, reactive one."},
   {"q":"Make the case for guarding the preparation window.","a":"Lose the preparation window, and every deadline becomes a crisis; protect it, and the same deadlines pass almost unnoticed."},
   {"q":"How would you sum up your leadership style around the calendar?","a":"My leadership here is deliberately quiet, unhurried and, in the end, decisive: I set the pace early so that no one ever has to sprint."},
   {"q":"Why is the calendar your most underrated control?","a":"What the calendar gives us is not merely order but peace of mind — and a function at peace makes far fewer of the errors that audits expose."}]}
]

