data["476"] = [
 {"title":"Open cloze (avançado) — Nominalização e arquitetura global (fiscal-taxes)","note":"Sem opções. O aluno produz o elemento que falta.","items":[
   {"q":"The ___ of the architecture is what distinguishes a strategy from an accident.","a":"deliberateness"},
   {"q":"The ___ of the business in the structure is what auditors look for first.","a":"reflection"},
   {"q":"The ___ of an entity in a low-tax jurisdiction must be justified by genuine substance.","a":"location / basing / establishment"},
   {"q":"The ___ of value through the group should mirror where it is actually created.","a":"flow"},
   {"q":"The ___ of risk by a given entity must match the return it receives.","a":"bearing / assumption"},
   {"q":"The ___ of an aggressive structure, once challenged, can take years.","a":"unwinding"},
   {"q":"The ___ of the footprint to commercial reality is our central defence.","a":"alignment"},
   {"q":"The ___ of the architecture, far from being incidental, is wholly deliberate.","a":"design"},
   {"q":"The ___ of a structure determines whether it is defensible or merely clever.","a":"substance"},
   {"q":"The ___ of the arrangement in a newspaper article would be deeply unwelcome.","a":"appearance / exposure"}]},
 {"title":"Key word transformation — nominalize a estrutura global (nominalização)","note":"Reescreva usando a palavra-chave (3–6 palavras).","items":[
   {"q":"The architecture is deliberate, and that matters.  ·  (DELIBERATENESS)  ·  The ___ matters.","a":"deliberateness of the architecture"},
   {"q":"The structure reflects the business.  ·  (REFLECTION)  ·  The ___ is essential.","a":"reflection of the business"},
   {"q":"Value flows through the group in a certain way.  ·  (FLOW)  ·  The ___ must mirror reality.","a":"flow of value"},
   {"q":"We had to unwind the structure, which took years.  ·  (UNWINDING)  ·  The ___ took years.","a":"unwinding of the structure"},
   {"q":"This entity bears the risk, and that justifies its return.  ·  (BEARING)  ·  The ___ justifies its return.","a":"bearing of the risk"},
   {"q":"We aligned the footprint with commercial reality.  ·  (ALIGNMENT)  ·  The ___ is our defence.","a":"alignment of the footprint"}]},
 {"title":"Register / paraphrase — eleve ao registro executivo (nominalização)","note":"Reescreva em registro formal usando nominalização.","items":[
   {"q":"We designed the architecture on purpose, not by accident.","a":"The deliberateness of the architecture distinguishes a strategy from a mere accident of history."},
   {"q":"The structure should reflect what the business actually does.","a":"The reflection of the genuine business in the structure is what makes the architecture defensible."},
   {"q":"Whichever entity carries the risk should get the return.","a":"The bearing of risk by an entity must correspond to the return it receives."},
   {"q":"It took us years to unwind that aggressive structure.","a":"The unwinding of the aggressive structure ultimately consumed several years."},
   {"q":"We line the footprint up with the real commercial picture.","a":"The alignment of the global footprint with commercial reality remains our principal defence."},
   {"q":"We'd hate to see this arrangement turn up in a newspaper.","a":"The appearance of the arrangement in a newspaper article would be wholly unwelcome."}]},
 {"title":"Error correction (editing) — ache e corrija o erro sutil (nominalização)","note":"Um erro de C1/C2 por frase. Corrija e diga por quê.","items":[
   {"q":"The deliberate of the architecture distinguishes strategy from accident.","a":"The deliberateness of the architecture distinguishes strategy from accident. (o nome é 'deliberateness')"},
   {"q":"The reflect of the business in the structure is essential.","a":"The reflection of the business in the structure is essential. (nome de 'reflect' é 'reflection')"},
   {"q":"The unwinding of the structure were lengthy.","a":"The unwinding of the structure was lengthy. (sujeito singular exige 'was')"},
   {"q":"The bearing of risk by this entity justify its return.","a":"The bearing of risk by this entity justifies its return. (núcleo singular exige 'justifies')"},
   {"q":"The alignment of the footprint with the commercial reality are our defence.","a":"The alignment of the footprint with commercial reality is our defence. (núcleo singular 'alignment' exige 'is')"},
   {"q":"The location an entity in a low-tax jurisdiction needs substance.","a":"The location of an entity in a low-tax jurisdiction needs substance. (nominalização exige 'of')"}]},
 {"title":"Advanced collocations & lexis — arquitetura tributária global (além da aula)","note":"Peça uma frase de registro formal com cada item.","items":[
   {"q":"a global tax footprint","a":"uma pegada tributária global"},{"q":"to base an entity","a":"sediar uma entidade"},
   {"q":"economic substance","a":"substância econômica"},{"q":"to unwind a structure","a":"desfazer uma estrutura"},
   {"q":"a defensible architecture","a":"uma arquitetura defensável"},{"q":"to carry commensurate risk","a":"suportar risco proporcional"},
   {"q":"the newspaper test","a":"o teste do jornal (reputacional)"},{"q":"to align form and substance","a":"alinhar forma e substância"},
   {"q":"a stable structure","a":"uma estrutura estável"},{"q":"to withstand the substance test","a":"passar no teste de substância"}]},
 {"title":"Discuss / Argue — arquitetura global no seu trabalho","note":"Respostas-modelo C1–C2 que o aluno adapta.","items":[
   {"q":"What distinguishes a deliberate tax architecture from an accidental one?","a":"It is the deliberateness of the architecture — the conscious reflection of the genuine business in the structure — that separates a defensible strategy from an accident of history."},
   {"q":"How do you ensure a structure can withstand scrutiny?","a":"I insist that the location of each entity be matched by genuine substance, so that the bearing of risk and the receipt of return always sit in the same place."},
   {"q":"Why is the 'newspaper test' part of your design thinking?","a":"Because the appearance of an arrangement in a newspaper article would be unwelcome, I design every structure to be explicable in plain language, not merely defensible in a tribunal."},
   {"q":"What is the cost of an over-aggressive structure?","a":"However elegant it may look, an aggressive structure carries a hidden cost: its unwinding, once challenged, can consume years and far exceed the tax it ever saved."},
   {"q":"How does substance relate to the global footprint?","a":"The alignment of the footprint with commercial reality is our central defence, for a structure without substance is merely clever until the moment it is tested."},
   {"q":"Why prize stability in a tax architecture?","a":"The stability of a structure is itself a virtue: an architecture that need not be redesigned with every ruling is one the board can rely on for the long horizon."}]}
]

