data["477"] = [
 {"title":"Open cloze (avançado) — Passado hipotético e tratados (fiscal-taxes)","note":"Sem opções. O aluno produz o elemento que falta.","items":[
   {"q":"Had we modelled the treaty positions in advance, the structure ___ have looked very different.","a":"would"},
   {"q":"If the relationship between the two states had not ___ , the relief would have endured.","a":"changed / evolved"},
   {"q":"Had the treaty ___ renegotiated earlier, we would not have been left exposed.","a":"been"},
   {"q":"We would have relied less on the treaty ___ we had foreseen the political shift.","a":"if / had"},
   {"q":"Had the relief ___ withdrawn, double taxation would have eroded the margin entirely.","a":"been"},
   {"q":"If we had treated the treaty as a weather forecast rather than a guarantee, we ___ have hedged.","a":"would"},
   {"q":"Had a navigator's mindset been ___ , we would have planned for the treaty's evolution.","a":"adopted / applied"},
   {"q":"The exposure would have been smaller ___ the treaty had been modelled dynamically.","a":"if / had"},
   {"q":"Had we ___ on the treaty alone, a single renegotiation could have undone the plan.","a":"relied"},
   {"q":"If the favourable article had ___ removed, our effective rate would have jumped.","a":"been"}]},
 {"title":"Key word transformation — para o passado hipotético (hypothetical past)","note":"Reescreva usando a palavra-chave (3–6 palavras).","items":[
   {"q":"We didn't model the positions, so the structure was wrong.  ·  (HAD)  ·  ___ , the structure would have been right.","a":"Had we modelled the positions"},
   {"q":"We relied on the treaty, so a renegotiation exposed us.  ·  (RELIED)  ·  Had we not ___ , the renegotiation would not have exposed us.","a":"relied on the treaty"},
   {"q":"The treaty wasn't renegotiated early, so we were left exposed.  ·  (RENEGOTIATED)  ·  Had the treaty ___ earlier, we would not have been exposed.","a":"been renegotiated"},
   {"q":"We didn't foresee the political shift, so we didn't hedge.  ·  (FORESEEN)  ·  Had we ___ , we would have hedged.","a":"foreseen the political shift"},
   {"q":"The relief was withdrawn, so double taxation hit the margin.  ·  (WITHDRAWN)  ·  Had the relief not ___ , the margin would have survived.","a":"been withdrawn"},
   {"q":"We treated the treaty as a guarantee, so we were caught out.  ·  (TREATED)  ·  Had we not ___ as a guarantee, we would have planned for change.","a":"treated the treaty"}]},
 {"title":"Register / paraphrase — eleve ao registro executivo (passado hipotético)","note":"Reescreva em registro formal com inversão condicional.","items":[
   {"q":"If we'd modelled the treaty positions first, things would have looked different.","a":"Had we modelled the treaty positions in advance, the structure would have looked materially different."},
   {"q":"We leaned on the treaty too much, and a renegotiation caught us out.","a":"Had we not relied so heavily on the treaty, a single renegotiation could not have caught us out."},
   {"q":"We didn't see the political change coming, so we didn't protect ourselves.","a":"Had we foreseen the political shift, we would have hedged the exposure accordingly."},
   {"q":"They removed the relief and double tax wiped out our margin.","a":"Had the relief not been withdrawn, double taxation would not have eroded the margin."},
   {"q":"We treated the treaty like a guarantee instead of a forecast.","a":"Had we treated the treaty as a forecast rather than a guarantee, we would have planned for its evolution."},
   {"q":"If we'd thought like a navigator, we'd have planned for the treaty changing.","a":"Had a navigator's mindset been adopted, we would have anticipated the treaty's evolution from the outset."}]},
 {"title":"Error correction (editing) — ache e corrija o erro sutil (passado hipotético)","note":"Um erro de C1/C2 por frase. Corrija e diga por quê.","items":[
   {"q":"Had we modelled the positions, the structure would looked different.","a":"Had we modelled the positions, the structure would have looked different. (condicional perfeito: 'would have looked')"},
   {"q":"If we would have foreseen the shift, we would have hedged.","a":"If we had foreseen the shift, we would have hedged. (a oração-'if' usa 'had foreseen', não 'would have')"},
   {"q":"Had the treaty renegotiated earlier, we would not have been exposed.","a":"Had the treaty been renegotiated earlier, we would not have been exposed. (passiva exige 'been renegotiated')"},
   {"q":"Had we not relied on the treaty, a renegotiation could not catch us out.","a":"Had we not relied on the treaty, a renegotiation could not have caught us out. (resultado passado: 'could not have caught')"},
   {"q":"Had the relief not withdrawn, the margin would have survived.","a":"Had the relief not been withdrawn, the margin would have survived. (passiva: 'been withdrawn')"},
   {"q":"If a navigator's mindset had been adopt, we would have planned.","a":"If a navigator's mindset had been adopted, we would have planned. (particípio 'adopted')"}]},
 {"title":"Advanced collocations & lexis — dupla tributação e tratados (além da aula)","note":"Peça uma frase de registro formal com cada item.","items":[
   {"q":"to claim treaty relief","a":"pleitear o benefício do tratado"},{"q":"a double-taxation treaty","a":"um tratado de bitributação"},
   {"q":"to be left exposed","a":"ficar exposto"},{"q":"to renegotiate an article","a":"renegociar um artigo"},
   {"q":"a favourable provision","a":"uma disposição favorável"},{"q":"treaty shopping","a":"escolha oportunista de tratado"},
   {"q":"to model dynamically","a":"modelar de forma dinâmica"},{"q":"a withholding rate","a":"uma alíquota de retenção na fonte"},
   {"q":"to erode the margin","a":"corroer a margem"},{"q":"the spirit of the treaty","a":"o espírito do tratado"}]},
 {"title":"Discuss / Argue — tratados e bitributação no seu trabalho","note":"Respostas-modelo C1–C2 que o aluno adapta.","items":[
   {"q":"Why shouldn't a treaty be treated as a permanent guarantee?","a":"Had we treated our key treaty as a guarantee rather than a forecast, a single renegotiation would have undone the plan; treaties evolve with the politics that underpin them."},
   {"q":"How do you build resilience against treaty change into a structure?","a":"Had we modelled the positions dynamically from the outset, we would not have been left exposed; accordingly, I now stress-test every structure against the treaty's withdrawal."},
   {"q":"Describe a situation where over-reliance on a treaty created risk.","a":"Had we relied less exclusively on the favourable article, the renegotiation that followed would not have caught us so badly exposed to double taxation."},
   {"q":"What does the 'navigator versus weather forecast' metaphor mean to you?","a":"A navigator does not assume the weather will hold; likewise, had we read our treaties as forecasts rather than fixed coordinates, we would have hedged the political risk in good time."},
   {"q":"How would you advise a colleague entering a new treaty jurisdiction?","a":"I would tell them that, had I myself modelled the downside of withdrawal earlier, I would have spared the group a costly scramble when the relief was unexpectedly curtailed."},
   {"q":"Why does the political relationship between states matter to your planning?","a":"Had the political relationship between the two states not deteriorated, our relief would have endured; since such relationships shift, I now treat treaty stability as a variable, never a constant."}]}
]

